def wordmark(color, x, y, size=40):
    d = WM44 if size == 44 else WM40
    return f'<path transform="translate({x} {y})" d="{d}" fill="{color}"/>'

def svg(w, h, body, extra=""):
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" width="{w}" height="{h}">{extra}{body}</svg>\n')

files = {}
# symbol only
files["mark.svg"] = svg(100, 100, mark(INK, CRIMSON))
files["mark-dark.svg"] = svg(100, 100, mark(CREAM, CRIMSON_D))
files["mark-mono.svg"] = svg(100, 100, mark("currentColor", "currentColor"))
# favicon: switches with OS theme
files["favicon.svg"] = svg(100, 100,
    f'<path class="m" d="{M_PATH}" fill="none" stroke-width="9" stroke-linejoin="round" stroke-linecap="round"/>'
    f'<path class="t" d="{TILDE}" fill="none" stroke-width="8" stroke-linecap="round"/>',
    extra=f'<style>.m{{stroke:{INK}}}.t{{stroke:{CRIMSON}}}@media(prefers-color-scheme:dark){{.m{{stroke:{CREAM}}}.t{{stroke:{CRIMSON_D}}}}}</style>')
# square avatars 512
def icon(bg, m, t):
    return svg(512, 512, f'<rect width="512" height="512" rx="96" fill="{bg}"/>' + mark(m, t, 76, 76, 3.6))
files["icon.svg"] = icon(CREAM, INK, CRIMSON)
files["icon-dark.svg"] = icon(CHAR, CREAM, CRIMSON_D)
files["icon-crimson.svg"] = icon(CRIMSON, CREAM, "#F5C26B")
# horizontal logo: mark + wordmark, transparent bg
def logo(m, t, w):
    return svg(310, 100, mark(m, t, 0, 0, 1.0) + wordmark(w, 108, 66))
files["logo.svg"] = logo(INK, CRIMSON, INK)
files["logo-dark.svg"] = logo(CREAM, CRIMSON_D, CREAM)
files["logo-mono.svg"] = logo("currentColor", "currentColor", "currentColor")
# stacked logo for README hero
def stacked(m, t, w):
    return svg(300, 225, mark(m, t, 80, 0, 1.4) + wordmark(w, 42.5, 205, 44))
files["logo-stacked.svg"] = stacked(INK, CRIMSON, INK)
